using System.IdentityModel.Tokens.Jwt; using System.Security.Claims; using System.Text; using InventorySystem.Domain.Entities; using Microsoft.AspNetCore.Identity; using Microsoft.Extensions.Configuration; using Microsoft.IdentityModel.Tokens;
namespace InventorySystem.Infrastructure.Services;
public class TokenService(IConfiguration config,UserManager<AppUser> users) { public async Task<string> GenerateTokenAsync(AppUser user){ var roles=await users.GetRolesAsync(user); var claims=new List<Claim>{new(JwtRegisteredClaimNames.Sub,user.Id),new(ClaimTypes.NameIdentifier,user.Id),new(ClaimTypes.Name,user.UserName??user.Email??string.Empty),new(JwtRegisteredClaimNames.Jti,Guid.NewGuid().ToString())}; claims.AddRange(roles.Select(r=>new Claim(ClaimTypes.Role,r))); var key=new SymmetricSecurityKey(Encoding.UTF8.GetBytes(config["Jwt:Key"]!)); var token=new JwtSecurityToken(config["Jwt:Issuer"],config["Jwt:Audience"],claims,expires:DateTime.UtcNow.AddHours(8),signingCredentials:new SigningCredentials(key,SecurityAlgorithms.HmacSha256)); return new JwtSecurityTokenHandler().WriteToken(token); } }
